/** Centred in the same 240×196 frame the other puzzle art uses. */
export function animalSvg(spec: AnimalSpec, label: string): string {
  const inner = OPENMOJI[spec.id] ?? "";
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 -36 240 196" role="img" aria-label="${label}"><svg x="36" y="-32" width="168" height="168" viewBox="0 0 72 72">${inner}</svg></svg>`;
}
